-- Eight supporting CMS guides only. Original article rows and published pointers are preserved.
do $content_seed$
declare seed jsonb:='[{"guide_key":"independent-dependent-volumes","content":{"version":1,"title":"Independent vs Dependent Guitar Volume Controls","slug":"independent-dependent-volumes","category":"potentiometers","intro":"Understand why one volume can silence both pickups in a combined selector position, and what changes when the pickup is connected to the wiper.","seo_title":"Independent vs Dependent Guitar Volume Controls","meta_description":"Understand why one volume can silence both pickups in a combined selector position, and what changes when the pickup is connected to the wiper.","indexable":true,"primary_intent":null,"related":["lp-controls","lugs","modern-50s","values"],"tools":["wiring","signal"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Begin with the symptom"}]},{"type":"paragraph","content":[{"type":"text","text":"On many two-volume passive guitars, selecting both pickups and turning either volume fully down silences the whole output. That can be normal operation rather than a failed pickup or selector. The two controls share a connection at the selector in that position. A volume wiper at the grounded end of its track can therefore ground the shared signal connection."}]},{"type":"paragraph","content":[{"type":"text","text":"Test the two single-pickup selector positions first. If each pickup works alone but the combined position goes silent only when one volume reaches zero, record that behaviour before assuming the harness is faulty. If a pickup is silent in its own position, investigate that separate fault rather than explaining everything as volume interaction."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Follow terminals, not diagram orientation"}]},{"type":"paragraph","content":[{"type":"text","text":"In the conventional volume arrangement used in Apparition terminal references, lug 3 is the signal-input end, lug 2 is the wiper/output and lug 1 is the grounded end. These identities describe the pot with the stated reference orientation. Confirm the actual part orientation, and keep its metal casing separate from the resistive track terminals."}]},{"type":"paragraph","content":[{"type":"text","text":"For two conventional volumes feeding a selector, the selector joins their wiper outputs when both pickups are selected. At minimum, one wiper reaches the grounded track end. That creates a low-resistance route from the shared output to ground. The practical result follows the connection topology, not the pot brand or an unexplained defect."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the independent arrangement changes"}]},{"type":"paragraph","content":[{"type":"text","text":"A commonly used independent-volume arrangement connects the pickup to the wiper and takes the outgoing signal from the opposite signal-side track end, with the other track end grounded. This exchanges input and output connections relative to the conventional arrangement; it does not rename the wiper or alter physical lug numbers."}]},{"type":"paragraph","content":[{"type":"text","text":"At zero, the pickup-connected wiper reaches ground, while the outgoing connection remains separated from that ground by the track. The other pickup is therefore not simply shorted through that control. Independent means a useful change in the zero-volume interaction. It does not mean the two sources or their loads are completely isolated."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The trade-off is still an electrical network"}]},{"type":"paragraph","content":[{"type":"text","text":"Changing the arrangement also changes the impedance seen by the pickup as the knob moves. The response and useful sweep can differ from the conventional circuit. Tone connections and treble-bleed placement also need to match the intended topology. Moving a single wire while retaining every other assumption can produce confusing results."}]},{"type":"paragraph","content":[{"type":"text","text":"Modern versus 50s tone wiring is another choice. It concerns where the tone network connects relative to the volume control and should not be treated as a synonym for independent volumes. Decide separately which interaction and tone connection you want."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A bounded bench check"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Disconnect the guitar from the amplifier and record the original wiring before making changes."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify each volume wiper and track end with the actual part drawing or an isolated resistance test."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare the signal and return paths in each selector position, including both volumes at zero and full."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"After continuity checks, compare control behaviour with the same cable and amplifier settings; do not treat a drawing as a promise about perceived sound."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Use the existing Les Paul control and lug guides for the conventional harness first. The Generator and Signal Forge links are references for their explicitly supported topologies; an independent-volume modification is not automatically covered by the current model."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"StewMac: volume-pot wiring and independent control","marks":[{"type":"link","attrs":{"href":"https://www.stewmac.com/video-and-ideas/online-resources/learn-about-guitar-pickups-and-electronics-and-wiring/understanding-guitar-wiring-part-3-how-is-a-volume-pot-wired/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: Les Paul wiring variants","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/tips-and-tricks/lespaulwiring"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"02f94e4e-46c2-529d-a961-0826d8b06eb1","template_key":"generic"},{"guide_key":"pickup-phase-switching","content":{"version":1,"title":"Pickup Phase Switching: Signal Polarity and Shield Ground","slug":"pickup-phase-switching","category":"pickups","intro":"Separate relative signal polarity from magnetic polarity, coil splitting and shielding before adding a phase switch.","seo_title":"Pickup Phase Switching: Signal Polarity and Shield Ground","meta_description":"Separate relative signal polarity from magnetic polarity, coil splitting and shielding before adding a phase switch.","indexable":true,"primary_intent":null,"related":["pickups","coil-split-guide","series-parallel-guide","push-pull-dpdt"],"tools":["wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Relative polarity is the useful question"}]},{"type":"paragraph","content":[{"type":"text","text":"A phase-reversing switch commonly exchanges one pickup’s signal and coil-return connections. This reverses its electrical signal polarity relative to another pickup. The familiar effect occurs when both signals are combined: their frequency-dependent contributions can reinforce or cancel differently."}]},{"type":"paragraph","content":[{"type":"text","text":"There is no second pickup signal to cancel against when that pickup is selected alone. A polarity reversal of the entire isolated pickup should therefore not be described as a new single-pickup equaliser. Additional switching, asymmetric wiring or a fault can change that conclusion, so establish which circuit is actually being switched."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why the result is not perfect cancellation"}]},{"type":"paragraph","content":[{"type":"text","text":"Neck and bridge pickups sense different locations on the string and need not have identical response or level. Reversing one signal in a combined position does not subtract two identical recordings. The surviving result depends on pickup placement, construction, wiring, control settings and load."}]},{"type":"paragraph","content":[{"type":"text","text":"Descriptions such as hollow or reduced low-frequency output are listening descriptions, not a universal numerical response or proof that the pickups are incorrectly manufactured. A deliberate out-of-phase combination is an option; it should be distinguished from an unexpected cancellation after replacing a pickup."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Keep chassis and shield grounded"}]},{"type":"paragraph","content":[{"type":"text","text":"A pickup with separate coil conductors and a shield/chassis conductor allows the coil connections to be exchanged while the shield remains connected to ground. The bare drain wire is not a interchangeable signal lead. Covers, baseplates and other exposed metal must keep their intended ground connection."}]},{"type":"paragraph","content":[{"type":"text","text":"A two-wire pickup can tie its coil return to its cover or baseplate internally. Reversing those two wires may put metal shielding on the signal connection. Single-coil construction can add further limitations involving pole pieces and coil insulation. Check the maker’s documented lead arrangement; do not assume every pickup can be reversed by a simple external swap."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"DPDT switching and coil modes"}]},{"type":"paragraph","content":[{"type":"text","text":"A suitable DPDT switch can exchange two signal connections using two poles. Verify the common contacts and both switch states with the disconnected part; rear-view orientation and manufacturer numbering vary. Use a documented wiring reference rather than copying six terminal numbers from an unrelated switch."}]},{"type":"paragraph","content":[{"type":"text","text":"Reversing an entire humbucker’s output is different from reversing one of its coils internally. The latter changes the relationship between the coils and may affect both string-signal addition and hum cancellation. Coil splitting and series/parallel switching are also separate operations. A combined control should be analysed state by state."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Troubleshoot the combination methodically"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm that each pickup has normal output when selected alone."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Document the maker’s coil, series-link and separate shield identities."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Test the switch contact pairs in both positions before installing jumpers."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep shields grounded and verify that no switch state shorts the output unexpectedly."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare the combined setting at matched volume settings; do not use wire colour alone to infer polarity."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The existing Generator can help inspect supported signal/ground routes. This article does not add a new phase-switch topology to the shared electrical authority."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: separate coil leads and chassis ground","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/2020/09/29/reverse-pickup-polarity-multiple-leads/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: limitations when reversing single-coil leads","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/2020/04/10/how-to-reverse-pickup-phase/comment-page-1/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: pickup polarity and phase","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/pickup-polarity-and-phase-made-simple"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"dcffb92c-4dd4-5ee1-a33e-962d32aec9cd","template_key":"generic"},{"guide_key":"push-pull-dpdt","content":{"version":1,"title":"Push/Pull Pots and DPDT Switching Fundamentals","slug":"push-pull-dpdt","category":"pickups","intro":"Treat a push/pull control as a potentiometer and a separate switch, then identify the two poles and their throw contacts before choosing a modification.","seo_title":"Push/Pull Pots and DPDT Switching Fundamentals","meta_description":"Treat a push/pull control as a potentiometer and a separate switch, then identify the two poles and their throw contacts before choosing a modification.","indexable":true,"primary_intent":null,"related":["pots","lugs","coil-split-guide","pickup-phase-switching","partial-coil-splits"],"tools":["wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Two devices share one control"}]},{"type":"paragraph","content":[{"type":"text","text":"A conventional push/pull guitar control combines a rotary potentiometer with a mechanically operated switch. The three resistive-track terminals still perform the pot’s normal task. The switch terminals are a separate contact system; pulling the shaft does not, by itself, tell you how the pot or pickups are connected."}]},{"type":"paragraph","content":[{"type":"text","text":"A DPDT switch means double-pole, double-throw: two separate common contacts can each connect to one of two throw contacts. The poles move together mechanically. That description does not require a connection between the poles and does not identify the contact numbering of your particular part."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Identify commons with a meter"}]},{"type":"paragraph","content":[{"type":"text","text":"Many push/pull switches present six contacts in two groups of three, but orientation and numbering are not universal. In a common layout, each middle contact is a pole common. Confirm that on the actual disconnected switch rather than relying on which row looks central in a photograph."}]},{"type":"paragraph","content":[{"type":"text","text":"For one pole, find the contact that connects to one neighbour in the pushed position and the other neighbour in the pulled position. Repeat for the second pole. Record the two contact maps. A continuity check is more informative than saying the switch is on or off because a DPDT typically selects between routes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fit is part of the specification"}]},{"type":"paragraph","content":[{"type":"text","text":"The potentiometer value and taper, shaft type, bushing length, thread, body depth and switch form all matter. A control that fits an SG cavity may not fit the same way in another instrument. Check the pot and switch drawing, available cavity depth and knob compatibility before ordering a replacement."}]},{"type":"paragraph","content":[{"type":"text","text":"The Bourns PDB183 datasheet is one example of a documented DPDT push/pull part. Its contact and dimension information applies to that model. It is not a universal drawing for CTS, Alpha or every Bourns variant. Avoid translating terminal numbers across products without verifying their functions."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose a complete switching task"}]},{"type":"paragraph","content":[{"type":"text","text":"Coil splitting can use a pole to route an accessible humbucker series junction toward ground. Relative phase reversal usually needs two poles to exchange two coil-signal connections while leaving the shield grounded. Other modifications require their own complete switching map."}]},{"type":"paragraph","content":[{"type":"text","text":"Count the independent routes needed in every state. A six-terminal switch is not automatically capable of every combination of split, series/parallel and phase functions at once. A pot fitted in the tone position can carry a switch function independently of its tone-track wiring, provided the complete documented circuit is retained."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Plan before soldering"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the three pot terminals, metal casing and six switch contacts distinct in your notes."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Label actual commons and throws using continuity measurements in both positions."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Check required pickup conductors and keep chassis/shield leads out of signal-reversing paths."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspect clearance so exposed terminals cannot contact shielding or adjacent parts."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Verify both switch states after assembly before reconnecting the amplifier."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Use the related coil-split and phase guides to understand the intended function before choosing a switch diagram. Supported Generator drawings remain the authority for the configurations they actually expose."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Bourns PDB183: switch type, contact drawing and dimensions","marks":[{"type":"link","attrs":{"href":"https://www.bourns.com/data/global/pdfs/PDB183.pdf"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: push/pull switching examples","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/2017/03/29/push-pull-pots-mods/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: push/pull installation context","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/how-to-add-push-pull-pot-wiring-to-a-les-paul-style-guitar"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"426a5076-1f07-5c4d-98e8-c0a8497b839d","template_key":"generic"},{"guide_key":"pickup-dc-resistance-output","content":{"version":1,"title":"Pickup DC Resistance Is Not an Output Rating","slug":"pickup-dc-resistance-output","category":"pickups","intro":"Use resistance measurements to investigate coil continuity and wiring state, while keeping output, inductance and electrical response separate.","seo_title":"Pickup DC Resistance Is Not an Output Rating","meta_description":"Use resistance measurements to investigate coil continuity and wiring state, while keeping output, inductance and electrical response separate.","indexable":true,"primary_intent":null,"related":["pickups","pickup-inductance","series-parallel-guide","coil-split-guide"],"tools":["signal"],"components":[],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the meter actually measures"}]},{"type":"paragraph","content":[{"type":"text","text":"A DC resistance reading measures opposition to a small direct current through the connected winding path. It is useful for checking continuity and comparing an identified coil with its documented specification. It is not a measurement of the voltage generated by a moving guitar string."}]},{"type":"paragraph","content":[{"type":"text","text":"A pickup’s resistance depends on winding length, conductor dimensions and material, as well as temperature. Two different designs can have similar resistance and substantially different magnetic systems or electrical behaviour. A larger resistance number does not establish a universally louder, better or more powerful pickup."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Compare like with like"}]},{"type":"paragraph","content":[{"type":"text","text":"Within one design family, resistance may help identify a winding variant because additional turns can also add wire length. Across different wire gauges, magnet systems and geometries, the same shortcut becomes unreliable. Read the maker’s output description and test conditions separately from the DCR figure."}]},{"type":"paragraph","content":[{"type":"text","text":"Actual generated voltage depends on string motion and the pickup’s transduction system, then interacts with the surrounding electrical load. Pickup height and the measurement setup matter. A catalogue’s DCR, resonant-peak and output descriptions should not be collapsed into a single ranking."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Measure the intended coil path"}]},{"type":"paragraph","content":[{"type":"text","text":"An installed measurement at the jack includes whatever the selector and controls connect. A pot track can provide a parallel resistance path, and another selected pickup can change the reading. A measurement lower than the isolated specification is not sufficient proof of a damaged winding."}]},{"type":"paragraph","content":[{"type":"text","text":"For an isolated measurement, disconnect the relevant conductors from parallel circuit paths as appropriate and follow the manufacturer’s lead identification. With a four-conductor humbucker, establish which leads belong to each coil and how the coils are connected. Treat the separate shield as shielding, not an extra winding terminal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Wiring modes change resistance without defining output"}]},{"type":"paragraph","content":[{"type":"text","text":"Two equal coils of resistance R give 2R in series and R/2 in parallel in the ideal DC resistance calculation. Selecting one coil gives approximately R. These are circuit relationships; the output voltage does not follow the same numerical ratios under every load or excitation."}]},{"type":"paragraph","content":[{"type":"text","text":"The measurement can still be a useful sanity check of a switching circuit. If a intended full-series state reads like one isolated coil, review the series junction and switch connections. If the reading is unstable, inspect leads and probe contact before deciding that the pickup itself is defective."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Record enough context"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the pickup model, lead arrangement, selected wiring state and whether the coil was isolated."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Allow measurements to stabilise and compare at similar temperatures; warmer copper winding resistance can be higher."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Avoid holding probe tips across the measurement path or treating a poor contact as an open winding."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the expected range from the actual maker, rather than an unrelated pickup with a similar name."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Investigate unusual readings together with continuity, mechanical condition and audible symptoms."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Signal Forge uses explicit pickup and loading assumptions for a bounded response model. A DCR reading alone does not supply all of those assumptions or predict a complete amplified sound."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: resistance and output are different measurements","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/pickup-resistance-vs-output"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan support: resistance measurement and temperature","marks":[{"type":"link","attrs":{"href":"https://seymourduncan.zendesk.com/hc/en-us/articles/360036534074-How-Can-I-Measure-the-DC-Resistance-of-a-Pickup"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: DC readings in different coil modes","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/swd/what-readings-do-you-get-if-a-humbucking-pickup-is-in-series-humbucking-split-out-of-phase-with-itself-and-parallel"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"e3cc71ac-1aa9-5f0c-928a-ca841fc07b9c","template_key":"generic"},{"guide_key":"pickup-inductance","content":{"version":1,"title":"Pickup Inductance: A Useful Circuit Parameter, Not a Tone Score","slug":"pickup-inductance","category":"pickups","intro":"Understand inductive impedance and resonance without treating a henry reading as a complete description of a pickup.","seo_title":"Pickup Inductance: A Useful Circuit Parameter, Not a Tone Score","meta_description":"Understand inductive impedance and resonance without treating a henry reading as a complete description of a pickup.","indexable":true,"primary_intent":null,"related":["pickup-dc-resistance-output","cable-capacitance","values","tone","series-parallel-guide"],"tools":["signal"],"components":[],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Inductance describes part of the winding behaviour"}]},{"type":"paragraph","content":[{"type":"text","text":"A pickup winding behaves as more than a DC resistance. Its changing current produces a changing magnetic field, and the winding’s inductance contributes frequency-dependent impedance. Inductance is measured in henries. A DC ohmmeter does not measure it."}]},{"type":"paragraph","content":[{"type":"text","text":"The winding and magnetic construction influence inductance. The pickup also has resistance, capacitance and losses. A useful model states those assumptions separately rather than treating the inductance number as a complete prediction of output or perceived sound."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frequency changes the opposition to current"}]},{"type":"paragraph","content":[{"type":"text","text":"For an ideal inductor, inductive reactance is proportional to frequency and inductance: XL = 2πfL. The equation describes an ideal circuit element. A real pickup is a transducer with additional winding and magnetic effects, not an isolated perfect inductor connected to an ideal source."}]},{"type":"paragraph","content":[{"type":"text","text":"This distinction explains why the same resistance reading can accompany different frequency response. It does not justify ranking pickups by inductance alone. Measurements need a stated method and operating frequency; two meters or test fixtures can report different equivalent values for a lossy device."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The surrounding circuit contributes to resonance"}]},{"type":"paragraph","content":[{"type":"text","text":"Inductance interacts with pickup winding capacitance and the capacitance presented by an unbuffered cable. A simple ideal LC estimate is f ≈ 1/(2π√LC). This is a bounded approximation, not the full response of a guitar with volume and tone controls."}]},{"type":"paragraph","content":[{"type":"text","text":"Resistance and losses affect the height and breadth of the response feature. The tone network is also frequency-dependent. Adding a tone capacitor to the circuit should not be interpreted as simply substituting that capacitor for every other capacitance in the ideal formula."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use measurements comparatively and state the setup"}]},{"type":"paragraph","content":[{"type":"text","text":"An isolated winding or documented pickup mode gives a more interpretable inductance test than an unknown installed harness. Record the test frequency, equivalent-series or parallel setting, fixture and whether the pickup is split, series-connected or parallel-connected."}]},{"type":"paragraph","content":[{"type":"text","text":"Core and metal losses can make an equivalent inductance frequency-dependent. Published values from different test methods may not be directly comparable. A practical comparison should hold the measurement method and surrounding load constant, and report uncertainty instead of inventing excessive precision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Turn the parameter into a useful question"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Which coil mode does the number describe?"}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"What cable capacitance and amplifier input are connected to the passive pickup?"}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Are pot resistance, knob position and tone connection the same in the comparison?"}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Does the measurement method match the maker’s stated conditions?"}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Which parts of the real instrument are outside the simplified model?"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Use Signal Forge to change one supported pickup or load assumption at a time. Keep its modelling limits separate from mechanical pickup placement, string motion, amplifier behaviour and listening preference."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: pickup inductance background","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/inductance-what-it-is-and-why-it-matters"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: pickup impedance and response","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/latest-updates/impedance-how-it-works-in-your-pickup"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: resistive and capacitive loading context","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/tips-and-tricks/250k-pots-versus-500k-pots-going-deeper-into-the-subject"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"79300908-8d47-5238-977e-b3ae0c23d572","template_key":"generic"},{"guide_key":"cable-capacitance","content":{"version":1,"title":"Guitar Cable Capacitance and the Passive Pickup Load","slug":"cable-capacitance","category":"wiring","intro":"Treat an unbuffered guitar cable as part of the electrical load, then distinguish capacitance per metre, total capacitance and buffered connections.","seo_title":"Guitar Cable Capacitance and the Passive Pickup Load","meta_description":"Treat an unbuffered guitar cable as part of the electrical load, then distinguish capacitance per metre, total capacitance and buffered connections.","indexable":true,"primary_intent":null,"related":["pickup-inductance","values","tone","bleeds","ground"],"tools":["signal","bleed"],"components":[],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A passive cable contributes capacitance"}]},{"type":"paragraph","content":[{"type":"text","text":"The signal conductor and surrounding shield are separated by insulating material. That geometry gives the cable capacitance between signal and return. In a passive guitar connection, it forms part of the frequency-dependent load seen by the pickup and controls."}]},{"type":"paragraph","content":[{"type":"text","text":"For the same cable construction, a longer length generally contributes more capacitance. The relationship is an electrical parameter, not evidence of a material having a preferred musical character. Construction, length, connector condition and handling noise are separate considerations."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Per-metre figures are not total cable figures"}]},{"type":"paragraph","content":[{"type":"text","text":"Cable datasheets may specify capacitance per metre or per foot, with a measurement frequency and temperature. Total cable capacitance is approximately the per-length figure multiplied by cable length, with connector and fixture contributions included where relevant."}]},{"type":"paragraph","content":[{"type":"text","text":"For example, a hypothetical 100 pF/m cable of 3 m contributes about 300 pF, while 6 m contributes about 600 pF before those extra contributions. This is an arithmetic illustration, not a specification for every cable. Check the actual manufacturer’s units before entering a value into a tool."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The pickup and controls determine the consequence"}]},{"type":"paragraph","content":[{"type":"text","text":"Cable capacitance interacts with pickup inductance and other circuit capacitances. Changing it can shift the electrical response and resonance. Pickup resistance, pot loading, tone settings and the amplifier input influence the observed result, so cable length alone is not a complete predictor."}]},{"type":"paragraph","content":[{"type":"text","text":"The effect of rolling down a conventional volume control also depends on the impedance between the pickup, wiper and cable. A treble-bleed network changes that frequency-dependent relationship. Choosing a bleed without stating cable/load assumptions can make two otherwise similar tests difficult to compare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A buffer changes which source drives the cable"}]},{"type":"paragraph","content":[{"type":"text","text":"After an appropriate low-output-impedance buffer, the following cable is driven by that buffer rather than directly by the passive pickup. The cable before the first active buffer remains part of the pickup-side circuit. Identify whether a pedal is actually buffered in the operating/bypass state being used."}]},{"type":"paragraph","content":[{"type":"text","text":"Active pickups and onboard electronics need their own stated output and load assumptions. Do not transfer a passive guitar’s cable calculation uncritically to every active instrument. The relevant question is the complete connection path, including which device drives each cable segment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A repeatable comparison"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the same guitar, pickup mode, volume/tone positions and amplifier input for the comparison."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Record cable length and capacitance units; measure an unplugged cable if the meter supports it."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate a capacitance comparison from crackle, broken connections or excessive handling noise."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Change one load assumption at a time in the supported tool; do not call a preference an objective improvement."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"When adding a buffer, record its location and bypass state so the pickup-side cable is still identified."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Signal Forge and Treble Bleed Designer expose supported load assumptions. Use a documented total capacitance estimate, and keep the model separate from a guarantee about the entire amplified rig."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Mogami W2524: capacitance units and stated conditions","marks":[{"type":"link","attrs":{"href":"https://mogamicable.com/category/products/W2524.php"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Seymour Duncan: resistive and capacitive pickup loading","marks":[{"type":"link","attrs":{"href":"https://www.seymourduncan.com/blog/tips-and-tricks/250k-pots-versus-500k-pots-going-deeper-into-the-subject"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"7b59d7ad-8054-597d-ab56-ac9c9ad11fda","template_key":"generic"},{"guide_key":"partial-coil-splits","content":{"version":1,"title":"Partial Coil Splits: Resistor Loading at the Series Junction","slug":"partial-coil-splits","category":"pickups","intro":"Understand what a partial-split resistor changes, why it is not a coil tap, and why the value belongs to a particular pickup and wiring arrangement.","seo_title":"Partial Coil Splits: Resistor Loading at the Series Junction","meta_description":"Understand what a partial-split resistor changes, why it is not a coil tap, and why the value belongs to a particular pickup and wiring arrangement.","indexable":true,"primary_intent":null,"related":["coil-split-guide","push-pull-dpdt","pickups","series-parallel-guide","pickup-dc-resistance-output"],"tools":["wiring"],"components":["potentiometers"],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start with the full humbucker connection"}]},{"type":"paragraph","content":[{"type":"text","text":"In a conventional series humbucker, two coils are connected through a series junction and their string-signal contributions combine. A full split commonly routes that junction to ground, bypassing one coil in the documented lead arrangement. The coil retained depends on which end is hot, which end is grounded and which junction is switched."}]},{"type":"paragraph","content":[{"type":"text","text":"Manufacturer wire colours identify leads only within that manufacturer’s scheme. Establish coil start/end, series link and separate shield identities before copying a switching diagram. A grounded shield should not become part of a coil-selection experiment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The resistor makes the bypass incomplete"}]},{"type":"paragraph","content":[{"type":"text","text":"In a partial-split arrangement, the switched series junction reaches ground through a resistor rather than a direct wire. The bypassed coil is therefore not simply removed by a zero-resistance short. The remaining contribution depends on that resistor and the pickup’s frequency-dependent impedances."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a circuit description. It does not supply a universal percentage split or a guaranteed match to a separate single-coil pickup. A humbucker’s two coils need not be identical, and cable, control settings and loading can change the practical comparison."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do not confuse a split with a tap"}]},{"type":"paragraph","content":[{"type":"text","text":"A coil tap requires an additional connection brought out from partway through a winding. Splitting a humbucker selects or bypasses a coil using the accessible inter-coil connection. A partial split uses a finite bypass resistance. These are different constructions and should not be described as interchangeable."}]},{"type":"paragraph","content":[{"type":"text","text":"Four-conductor humbuckers often expose the connections needed for external coil-mode switching, but the available leads and internal construction still need verification. A vintage-style two-conductor lead does not automatically expose the series junction needed for this modification."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose values in a stated context"}]},{"type":"paragraph","content":[{"type":"text","text":"A resistor value recommended by a pickup maker belongs to the stated pickup and wiring example. Fralin publishes partial-split examples; those examples should not be treated as a universal value for every humbucker. A different winding or retained coil can need a different compromise."}]},{"type":"paragraph","content":[{"type":"text","text":"Compare a documented full-series state, a full split and the proposed partial split under the same pickup height, cable and control settings. Record which coil remains directly in the signal path. A partial split does not guarantee full hum cancellation, and the residual noise behaviour must be evaluated rather than assumed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Verify both switch positions"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Measure the isolated switching contacts first and identify the actual common/throw pairs."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm the full-series state keeps the intended junction and does not route the output to ground."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm the split state reaches the junction through the chosen resistor and keeps the shield grounded."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Check resistance/continuity as a wiring sanity check, not as a complete output measurement."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Insulate exposed resistor leads and inspect clearance to pot casings and cavity shielding."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Read the existing coil-splitting guide before treating the partial-split connection as a modification. The Generator link supports only its documented configurations; this article does not extend the shared electrical model."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: documented partial-split switching example","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/diagram/coil-split-two-pickups-partial-split-resistor/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: resistor application context","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/product/resistors/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Fralin: push/pull and partial-split explanation","marks":[{"type":"link","attrs":{"href":"https://www.fralinpickups.com/2017/03/29/push-pull-pots-mods/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"898c73f0-3457-5b83-8f29-bedd380fa004","template_key":"generic"},{"guide_key":"output-jack-faults","content":{"version":1,"title":"Output Jack Wiring and Common Passive Guitar Faults","slug":"output-jack-faults","category":"troubleshooting","intro":"Identify jack TIP and SLEEVE by function, then separate contact, mechanical and solder faults from pickup or control problems.","seo_title":"Output Jack Wiring and Common Passive Guitar Faults","meta_description":"Identify jack TIP and SLEEVE by function, then separate contact, mechanical and solder faults from pickup or control problems.","indexable":true,"primary_intent":null,"related":["ground","grounding-guide","troubleshoot","lugs"],"tools":["wiring"],"components":[],"published_at":"2026-10-05","content_updated_at":"2026-10-05","body":{"version":1,"slots":{"main":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Identify the two electrical connections"}]},{"type":"paragraph","content":[{"type":"text","text":"For a conventional passive mono instrument output, the plug TIP carries the signal and the SLEEVE is the common return/shield connection. Identify the corresponding jack contacts using the actual part drawing or continuity to an inserted plug. Do not assign them by solder-lug length or a photograph’s orientation."}]},{"type":"paragraph","content":[{"type":"text","text":"Open-frame, enclosed, stereo and switching jacks can have different contact layouts. Extra terminals can provide a ring connection or switched contacts. Active instruments may use a jack contact for battery switching. Follow that circuit’s documentation rather than grounding every unused-looking terminal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Check the cable before opening the instrument"}]},{"type":"paragraph","content":[{"type":"text","text":"A faulty cable or plug can imitate a loose jack, intermittent solder joint or silent pickup. Try a known-working instrument cable and a known-working input before replacing guitar parts. Record whether moving the plug, rotating it or changing selector positions reproduces the fault."}]},{"type":"paragraph","content":[{"type":"text","text":"With the guitar unplugged from the amplifier, continuity checks can trace the cable TIP and SLEEVE to the intended jack terminals. Avoid measuring resistance on an energised circuit. This guide covers instrument electronics, not work inside amplifiers or their power supplies."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mechanical looseness can become an electrical problem"}]},{"type":"paragraph","content":[{"type":"text","text":"A jack that rotates when its mounting nut loosens can twist or strain attached wires. Prevent the jack body turning while addressing its mounting hardware, and check for suitable clearance and washers. Use the actual part’s installation instructions; excessive force can damage hardware or the instrument."}]},{"type":"paragraph","content":[{"type":"text","text":"Inspect whether the plug engages the intended contacts and whether a contact or terminal touches conductive cavity shielding. A terminal that only shorts when the jack is installed can make the loose assembly appear healthy on the bench. Inspect the assembled clearances, not just a free-floating drawing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Separate an open connection from a short"}]},{"type":"paragraph","content":[{"type":"text","text":"A broken signal connection, failed TIP contact or fractured joint can interrupt the output. A signal terminal contacting ground can also produce silence. A poor return path can produce noise or intermittency. The symptom alone does not uniquely identify which connection failed."}]},{"type":"paragraph","content":[{"type":"text","text":"Compare continuity across the intended cable contact and jack terminal while gently moving the disconnected assembly. Inspect the joint, conductor and strain path. Test the circuit’s signal-to-ground resistance in a documented selector/control state, since pot and pickup paths make that reading different from an isolated bare jack."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Before deciding to replace the part"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm the external cable and amplifier input first."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify TIP/SLEEVE electrically with the correct plug and actual part reference."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Check mounting rotation, wire strain, contact engagement and clearance to shielding."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspect intended connections for intermittency while the instrument is disconnected."}]}]},{"type":"list_item","content":[{"type":"paragraph","content":[{"type":"text","text":"After any repair, verify the installed assembly and every selector/control state used in normal operation."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Wiring Diagram Generator can show the supported instrument signal path to jack TIP and return to SLEEVE. Keep those terminal identities distinct; changing a jack drawing should never reverse the circuit’s signal and return authority."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References and scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Switchcraft 11: mono two-conductor jack reference","marks":[{"type":"link","attrs":{"href":"https://www.switchcraft.com/1-4-mono-2-conductor-jack-w-nut-and-washer-open-circuit/11/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Switchcraft: manufacturer drawings with TIP/SLEEVE identities","marks":[{"type":"link","attrs":{"href":"https://www.switchcraft.com/assets/1/24/11W07-W11_CD.pdf"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"This guide describes passive instrument electronics. Verify the actual part documentation and disconnected circuit before changing a connection. Tool links below are for supported configurations and do not imply that every modification in this guide is modelled."}]}]}}}},"id":"c9a9f8c9-9faf-5670-90d7-90986ae7ceee","template_key":"generic"}]'::jsonb; item jsonb; article_id uuid; revision_id bigint;
begin
 for item in select value from jsonb_array_elements(seed) loop
  article_id:=(item->>'id')::uuid;
  if exists(select 1 from public.hub_articles where (guide_key=item->>'guide_key' or draft->>'slug'=item->'content'->>'slug') and id<>article_id) then raise exception 'Content expansion identity/slug collision';end if;
  insert into public.hub_articles(id,guide_key,draft,seed_context) values(article_id,item->>'guide_key',item->'content',jsonb_build_object('template_key','generic','expected_intent',null,'refs','{}'::jsonb,'slots',jsonb_build_array('main'))) on conflict(id) do nothing;
 end loop;
 for item in select value from jsonb_array_elements(seed) loop
  article_id:=(item->>'id')::uuid;
  if (select published_revision_id from public.hub_articles where id=article_id) is null then
   insert into public.hub_article_revisions(article_id,revision_number,content,action,actor) values(article_id,1,item->'content','IMPORT',null) returning id into revision_id;
   update public.hub_articles set published_revision_id=revision_id where id=article_id and published_revision_id is null;
  end if;
 end loop;
 -- Validate only after all supporting public relationships exist; any failure rolls back the whole seed.
 for item in select value from jsonb_array_elements(seed) loop
  perform public.hub_validate_content(item->'content',(select seed_context from public.hub_articles where id=(item->>'id')::uuid),true);
 end loop;
end $content_seed$;
